G(9,()=>{const s1=pick([10,18,35,42]),v1=pick([1,2,3]),s2=pick([10,18,35,42]),v2=pick([1,2,3]);if(s1===s2)return null;const g=s1*v1+s2*v2,V=v1+v2;const S=g/V;if(!Number.isInteger(S*10))return null;
 return NUM(S,{q:`★ Смешали ${v1} л воды солёностью ${s1}‰ и ${v2} л воды солёностью ${s2}‰. Какая солёность у смеси (в ‰)?`,short:`(${s1}·${v1} + ${s2}·${v2}) : ${V} = ${N(S)}‰.`,
  explain:`Соли: ${M(`${s1} · ${v1} + ${s2} · ${v2} = ${s1*v1} + ${s2*v2} = ${g} г`)}. Литры: ${M(`${v1} + ${v2} = ${V} л`)}. Солёность: ${M(`${g} : ${V} = ${N(S)}‰`)}.<div class="box err"><b>Ловушка</b>Нельзя просто взять среднее (${s1} + ${s2}) : 2, если литров разное количество.</div>`,
  explain2:`Сначала посчитай, сколько всего соли (в граммах), потом раздели на все литры.`});},{star:true});
