function onTheory(root){
 const c=root.querySelector('#w-cycle');
 if(c){c.innerHTML=`<b>💧 Путешествие капли: нажимай «Дальше»</b>${BTNS([['cyN','Дальше ▶'],['cyA','Показать всё']])}<div id="cyP" class="fig"></div><div id="cyT" style="text-align:center;line-height:1.6;min-height:3em"></div>`;
  let st=0;const g=id=>c.querySelector('#'+id);const u=()=>{g('cyP').innerHTML=figCycle(st);g('cyT').innerHTML=st==null?'Все звенья вместе: вода возвращается в океан и снова испаряется — круг замкнулся!':`<b>${st+1}. ${CYC[st][0]}</b> — ${CYC[st][1]}`;};
  g('cyN').onclick=()=>{st=st==null?0:(st+1)%5;u();};g('cyA').onclick=()=>{st=null;u();};u();}
 const f=root.querySelector('#w-floor');
 if(f){f.innerHTML=`<b>🤿 Батискаф: двигай его над дном</b>${SL('fX','Положение:',46,330,1,70)}<div id="fP" class="fig"></div><div id="fT" style="text-align:center;line-height:1.6;min-height:3em"></div>`;
  const g=id=>f.querySelector('#'+id);const u=()=>{const x=+g('fX').value;const d=Math.round(floorAt(x)/10)*10;const z=zoneAt(x);g('fXo').textContent='';g('fP').innerHTML=figOceanFloor({x});g('fT').innerHTML=`Глубина: <span class="out">${N(d)} м</span> · <b>${z[0]}</b><br><span class="small">${z[1]}</span>`;};
  g('fX').oninput=u;u();}
}

